    tokenisedTitle: 'ເນື້ອຫາ Tokenised ແລະ ຄວາມເປັນເຈົ້າຂອງແບບແບ່ງສ່ວນ',
    tokenisedSubtitle: 'ການ Tokenise ເນື້ອຫາ ERC-1155 ແບບປະຕິວັດ',
    tokenisedDesc: 'ການອັບໂຫຼດ ຫຼື ການສະຕຣີມສົດໃດໆເທິງ DeHub ສາມາດ mint ເປັນ NFT ERC-1155 ທີ່ແບ່ງເປັນ 1,000 ຊິ້ນພໍດີ. ການ mint ແມ່ນທາງເລືອກ: ໂພສຈະເຜີຍແຜ່ແບບ off-chain ທັນທີທີ່ທ່ານສົ່ງ — ບໍ່ຕ້ອງໃຊ້ກະເປົາເງິນ, ບໍ່ຕ້ອງລົງລາຍເຊັນ, ບໍ່ມີຄ່າ gas — ແລະ ທ່ານສາມາດ mint ມັນໄດ້ທຸກເວລາທີ່ຕ້ອງການຈາກໂພສນັ້ນເອງ. ເມື່ອ mint ແລ້ວ, ຜູ້ສ້າງມີການຄວບຄຸມຢ່າງສົມບູນວ່າຈະຂາຍ ຫຼື ເກັບໄວ້ຈັກສ່ວນ, ສ້າງຮູບແບບການສ້າງລາຍໄດ້ແບບໃໝ່ທີ່ແຟນໆສາມາດລົງທຶນໃນເນື້ອຫາທີ່ພວກເຂົາເຊື່ອວ່າຈະປະສົບຜົນສຳເລັດ — ໂດຍພື້ນຖານແລ້ວແມ່ນການ "ເດີມພັນ" ກັບອະນາຄົດຂອງດາວທີ່ມີສັກກະຍະພາບ ຜ່ານຮູບແບບໂທເຄັນແຟນທີ່ປະຕິວັດ.',
