    futureDesc: 'ຮູບແບບເນື້ອຫາທີ່ແບ່ງສ່ວນ ERC-1155 ຂອງ DeHub ສະແດງເຖິງວິວັດທະນາການຈາກຄວາມສຳພັນຊົ່ວຄາວລະຫວ່າງຜູ້ສ້າງ ແລະ ແຟນ ໄປສູ່ການເປັນຄູ່ຮ່ວມທາງເສດຖະກິດແບບຖາວອນ. ໂດຍການໃຫ້ຜູ້ສ້າງ mint ການອັບໂຫຼດໃດໆເປັນ 1,000 ສ່ວນທີ່ຊື້ຂາຍໄດ້, ພວກເຮົາກຳລັງສ້າງແພລດຟອມທຳອິດທີ່ຄວາມສຳເລັດຂອງເນື້ອຫາເປັນປະໂຫຍດໂດຍກົງ ແລະ ຖາວອນແກ່ທຸກຄົນທີ່ກ່ຽວຂ້ອງ — ຜູ້ສ້າງ, ແຟນ ແລະ ນັກລົງທຶນ — ຕະຫຼອດໄປ, ໂດຍບໍ່ຕ້ອງໃຊ້ຄວາມພະຍາຍາມຢ່າງຕໍ່ເນື່ອງ ຫຼື ເພິ່ງພາແພລດຟອມ.',
