    topUpDesc: 'ພວກເຮົາມີຂອງພວກເຮົາໃນສະກຸນເງິນ APP, ຄ້າຍຄືກັບ Vbucks ທີ່ທ່ານໄດ້ຮັບໃນສະກຸນເງິນ Fortnite ຫຼື TikTok, ຂອງພວກເຮົາເອີ້ນວ່າ DeHub tokens. ທ່ານຈະເຫັນພວກນີ້ເປັນເງິນຄໍາໃນທົ່ວ app ໄດ້. ພວກມັນຖືກ ນໍາ ໃຊ້ ສໍາ ລັບບໍລິການທີ່ມີຄ່າສູງເຊັ່ນ: ຄໍາ ແນະ ນໍາ, ການສະ ຫມັກ ໃຊ້ແລະອື່ນໆ. ການທ່ອງເວັບແມ່ນບໍ່ເສຍຄ່າ, ແລະດັ່ງນັ້ນການໂພສພາຍໃນເງິນອຸດຫນູນປະ ຈໍາ ວັນທຸກໆບັນຊີໄດ້ຮັບ — ຖ້າທ່ານລົງທະບຽນກັບ Socials, Email ຫຼື SMS, ພວກເຮົາສະ ຫນັບ ສະ ຫນູນ ຄ່າ ທໍາ ນຽມອາຍແກັສທັງ ຫມົດ ສໍາ ລັບທ່ານ. ຜູ້ໃຊ້ກະເປົາເງິນຈ່າຍອາຍແກັສ ETH ຫຼື BnB ມາດຕະຖານ. ຕື່ມເງິນໃນ 2 ຄລິກຂ້າງລຸ່ມນີ້.',
