    multipostB2: 'ສົ່ງສິນເຊື່ອ:',
    multipostB2Desc: 'ການຈັດສົ່ງແຕ່ລະຄັ້ງໃຊ້ຈ່າຍສິນເຊື່ອຕໍ່ເວທີ, ລາຄາປະມານສິ່ງທີ່ເວທີນັ້ນໃຊ້ຈ່າຍເພື່ອບັນລຸ. ການກູ້ຢືມແມ່ນຊື້ດ້ວຍເຄື່ອງ ຫມາຍ DeHub, ມີສ່ວນຫຼຸດໃນຊຸດທີ່ໃຫຍ່ກວ່າ, ແລະທຸກສິ່ງທີ່ທ່ານຂາດແມ່ນຊື້ເມື່ອທ່ານໂພສ.',
    multipostB3: 'ກຳນົດເວລາ:',
    multipostB3Desc: 'ການໂພສທີ່ຖືກ ກໍາ ນົດອອກໄປຫາບັນຊີອື່ນໆຂອງທ່ານເມື່ອມັນຖືກເຜີຍແຜ່; ການປ່ອຍສິນເຊື່ອຂອງມັນຖືກໃຊ້ຈ່າຍເມື່ອທ່ານ ກໍາ ນົດມັນ.',
    communitiesB1Desc: 'ຄົ້ນພົບຊຸມຊົນຈາກ ຫນ້າ ຊຸມຊົນແລະເຂົ້າຮ່ວມໃນ ຫນຶ່ງ ແຖບ. ຊຸມຊົນເອກະຊົນເອົາຄໍາຮ້ອງຂໍເຂົ້າຮ່ວມ, ເຊິ່ງເຈົ້າຂອງອະນຸມັດ, ແລະກິດຈະກໍາໃຫມ່ສະແດງໃຫ້ເຫັນວ່າເປັນປ້າຍທີ່ບໍ່ໄດ້ອ່ານໃນການເດີນເຮືອ.',
    communitiesB2Desc: 'ແຕ່ລະຊຸມຊົນມີການໃຫ້ອາຫານແລະການສົນທະນາທີ່ອຸທິດຕົນເຊິ່ງສະມາຊິກໂພສ, ປຶກສາຫາລື, ດໍາ ເນີນການ ສໍາ ຫຼວດ, @ ເວົ້າເຊິ່ງກັນແລະກັນແລະ TIP, ປານກາງໂດຍເຈົ້າຂອງຊຸມຊົນ.',
    walletHubB1Desc: 'ກະເປົາເງິນຫຼາຍຕ່ອງໂສ້ຖື DeHub tokens ຄຽງຄູ່ກັບ ETH, BNB, USDT, USDC ແລະອື່ນໆໃນທົ່ວ Base, BNB Chain, Ethereum, Robinhood Chain ແລະ Arc, ບວກກັບການຖື Solana ຂອງທ່ານ. Zero Balances ແມ່ນເຊື່ອງໄວ້, ແລະ app ຖາມວ່າເຄືອຂ່າຍໃດທີ່ທ່ານຫມາຍຄວາມວ່າກ່ອນທີ່ຈະສໍາເນົາທີ່ຢູ່. ຮັບ, ສົ່ງ, ຊື້, ການຄ້າ, ສະເຕກ, ຂົວແລະເງິນສົດແມ່ນທັງ ຫມົດ ຫນຶ່ງ ແຕະຈາກຍອດເງິນ.',
    walletHubB3Desc: 'ຕື່ມເງິນເຂົ້າໃນແອັບພລິເຄຊັນຜ່ານ DeHub Pay, ໂດຍບັດຫລືດ້ວຍ crypto ຈາກຕ່ອງໂສ້ອື່ນ, ຈາກ $ 0.50.',
    walletHubB4Desc: 'Stake DeHub tokens — ໃນ Base ທໍາອິດ — ເພື່ອຫາລາງວັນແລະປົດລັອກລະດັບ badge ທີ່ຫຼຸດຄ່າທໍານຽມຂອງທ່ານ, ແລະ tokens ຂົວລະຫວ່າງ BnB Chain ແລະ Base.',
    walletHubB5Desc: 'ສະໝັກສະເພາະ Solana ທີ່ມີຂອງການຕິດຕາມກັບ Settings ເຊີນການສະໝັກສະເພາະທີ່ມີຂອງບໍ່ມີຂອງການຕິດຕາມກັບການຕັດສະນະຂອງ Jupiter ທີ່ມີຂອງການຕັດສະນະທີ່ມີຂອງການຕິດຕາມກັບການຕັດສະນະຂອງ Jupiter',
    tocExchange: 'ສະແດງສູນຄວາມທີ່ຈະກະຕິກັນກັນກັນກັນກັນ',
    exchangeTitle: 'ສະແດງສູນຄວາມທີ່ຈະກະຕິກັນກັນກັນກັນກັນ',
