    evenIfConclusion: 'ຂໍ້ຄວາມທີ່ຖືກເຂົ້າລະຫັດຂອງທ່ານຍັງບໍ່ສາມາດອ່ານໄດ້. ນັ້ນແມ່ນພະລັງງານຂອງການເຂົ້າລະຫັດຈາກຕອນທ້າຍໄປຫາຕອນທ້າຍ.',
    commitmentDesc: 'ໃນ DeHub ພວກເຮົາເຊື່ອວ່າຄວາມເປັນສ່ວນຕົວແມ່ນສິດທິພື້ນຖານ. ຂໍ້ຄວາມທີ່ຖືກກວມເອົາແມ່ນຖືກປົກປ້ອງໂດຍວິທະຍາສາດ, ບໍ່ແມ່ນພຽງແຕ່ນະໂຍບາຍເທົ່ານັ້ນ, ໂດຍໃຊ້ຫ້ອງສະ ຫມຸດ cryptographic ທີ່ຖືກກວດສອບແລະຖືກທົບທວນຄືນຢ່າງກວ້າງຂວາງແລະອະລູຈິຕັມ. ບ່ອນທີ່ບາງສິ່ງບາງຢ່າງຍັງບໍ່ຖືກກວມເອົາ — ຮູບພາບ, ວິດີໂອ ແລະໄຟລ໌, ຫຼືການສົນທະນາກັບຜູ້ໃດຜູ້ ຫນຶ່ງ ທີ່ບໍ່ໄດ້ເປີດເຜີຍການກວມເອົາ — ພວກເຮົາເວົ້າຢ່າງຈະແຈ້ງ.',
