    thirdPartyItem10Prefix: 'ການໂພສຫຼາຍຄັ້ງ:',
    thirdPartyItem10: 'ເມື່ອທ່ານເຊື່ອມຕໍ່ບັນຊີສັງຄົມອື່ນໆ, ການໂພສທີ່ທ່ານເລືອກທີ່ຈະສົ່ງແມ່ນຖືກສົ່ງໄປຫາເວທີເຫຼົ່ານັ້ນຜ່ານການບໍລິການໂພສ, ແລະໃຫ້ Farcaster ຜ່ານຜູ້ເຊັນທີ່ທ່ານອະນຸມັດ',
    dataSovereigntyItem5: 'ທ່ານເລືອກວ່າລະບົບ AI ສາມາດຝຶກອົບຮົມວຽກງານຂອງທ່ານໄດ້ຫຼືບໍ່. ມັນ ຖືກ ອະ ນຸ ຍາດ ເວັ້ນ ເສຍ ແຕ່ ວ່າ ທ່ານ ປິດ ມັນ ໃນ ການ ຕັ້ງ ຄ່າ, ແລະ ທາງ ເລືອກ ຂອງ ທ່ານ ໄດ້ ຖືກ ເຜີຍ ແຜ່ ໃຫ້ crawlers ກ່ຽວ ກັບ ຫນ້າ ທີ່ ທີ່ ພວກ ເຮົາ ຄວບ ຄຸມ',
