    prereq1: 'ໂປຣແກຣມທ່ອງເວັບ ຫຼື ແອັບພລິເຄຊັນ Android ຈາກ Google Play',
    prereq2: 'ບັນຊີ Google, Apple ຫຼື Telegram, ທີ່ຢູ່ອີເມວ, ເບີໂທລະສັບຫລືລະຫັດຜ່ານ — ຫຼືກະເປົາເງິນທີ່ທ່ານໃຊ້ແລ້ວ',
    prereq3: 'ບໍ່ມີຫຍັງອີກ: ບໍ່ມີປະໂຫຍກເມັດທີ່ຈະຂຽນລົງແລະບໍ່ມີອາຍແກັສທີ່ຈະຊື້',
    step1Title: 'ສ້າງບັນຊີຂອງທ່ານ',
    step1Desc: 'ເປີດ dehub.io ແລະແຕະ ເຂົ້າສູ່ລະບົບ. ເລືອກ Google, Apple, Telegram, ອີເມວ, SMS, passkey ຫຼືກະເປົາເງິນ. ກະເປົາເງິນທີ່ບໍ່ແມ່ນການຮັກສາຖືກສ້າງຂື້ນ ສໍາ ລັບທ່ານໃນພື້ນຫລັງ - ທ່ານຖືປຸ່ມ — ແລະແກັສແມ່ນໄດ້ຮັບການສະ ຫນັບ ສະ ຫນູນ, ສະນັ້ນບໍ່ມີຫຍັງທີ່ຈະສະ ຫນັບ ສະ ຫນູນ ກ່ອນທີ່ທ່ານຈະເລີ່ມຕົ້ນ.',
    step2Title: 'ສ້າງໂປຣໄຟລ໌ຂອງທ່ານ',
    step2Desc: 'ໃນໂປຣໄຟລ໌ການຕັ້ງຄ່າເພີ່ມຊື່ສະແດງ→ , ຊື່ຜູ້ໃຊ້, ອາວາຕາ, ຮູບພາບກວມເອົາແລະຊີວະປະຫວັດ, ແລະເຊື່ອມຕໍ່ສັງຄົມອື່ນໆຂອງທ່ານເພື່ອໃຫ້ໂປຣໄຟລ໌ຂອງທ່ານສະແດງໃຫ້ເຫັນການເຂົ້າເຖິງທັງ ຫມົດ ຂອງທ່ານ. → ເລືອກຫົວຂໍ້ໃນ Settings Appearance ໃນຂະນະທີ່ທ່ານຢູ່, ແລະເອົາທາງເລືອກທີ່ນໍາພາໂດຍຜ່ານຖ້າທ່ານຕ້ອງການທີ່ຈະໄດ້ຮັບການສະແດງປະມານ.',
    step3Title: 'ເຮັດໃຫ້ Post ທໍາອິດຂອງທ່ານ',
    step3Desc: 'ແຕະ ສ້າງ. ຂຽນຂໍ້ຄວາມ, ເພີ່ມຮູບພາບ, ວິດີໂອຫຼືສຽງ, ປ່ຽນເປັນບົດຄວາມ ສໍາ ລັບການຂຽນແບບຍາວ, ຫຼືໄປສົດ. ການໂພສແມ່ນຟຣີເຖິງເງິນອຸດຫນູນປະຈໍາວັນ — ສິບຂໍ້ຄວາມແລະ gigabyte ຂອງສື່ມວນຊົນຕໍ່ມື້ໂດຍບໍ່ມີປ້າຍ. ການຂຸດຄົ້ນຂໍ້ຄວາມໃນຕ່ອງໂສ້ແມ່ນທາງເລືອກແລະສາມາດເຮັດໄດ້ໃນເວລາຕໍ່ມາ.',
    step4Title: 'ໄດ້ຮັບຈາກຜູ້ຊົມຂອງທ່ານ',
    step4Desc: 'ທຸກໆຂໍ້ຄວາມສາມາດຖືກພິມໃສ່ໃນເຄື່ອງ ຫມາຍ DeHub. ຈາກນັ້ນທ່ານສາມາດຂາຍການສະ ຫມັກ ໃຊ້, ເຜີຍແຜ່ບົດຄວາມທີ່ຈ່າຍຕໍ່ການເບິ່ງ, ກໍາ ນົດ ຄໍາ ແນະ ນໍາ ຕ່ ໍາ ສຸດ ສໍາ ລັບຂໍ້ຄວາມໂດຍກົງ, ເປີດຮ້ານ, ໂພດ bounties ແລະແບ່ງປັນລິ້ງພົວພັນຂອງທ່ານເພື່ອຫາລາຍໄດ້ຈາກຄົນທີ່ທ່ານ ນໍາ ເຂົ້າ.',
    step5Title: 'ຍັງບັນຄວາມຕາຍຕະພັນທີ່ສຸດທີ່ສາມາດກະຕິກັນກັນກັບຕາຍຕະພັນນີ້',
    step5Desc: 'ຫຼືວ່າລາວຢາກເປັນສ່ວນຫນຶ່ງຂອງກຸ່ມ, ຫຼືຈະສະແດງຄວາມແຂງແຮງຕໍ່ ຫມູ່ເພື່ອນຂອງລາວ. ປ້າຍ ກໍາ ກັບຫຼຸດຄ່າ ທໍາ ນຽມຂອງທ່ານ, ເພີ່ມເງິນອຸດຫນູນການໂພດຂອງທ່ານ, ປົດລັອກ SuperPowers ແລະເພີ່ມນ້ ໍາ ຫນັກ ໃສ່ທັດສະນະ, ປະຕິກິລິຍາແລະສຽງຂອງທ່ານ.',
    step6Title: 'ໃຊ້ວອລເລັດຂອງທ່ານ',
    step6Desc: 'ກະເປົາເງິນຂອງທ່ານຖື DeHub tokens ແລະ crypto ອື່ນໆໃນຫລາຍຕ່ອງໂສ້. ຊື້ tokens ໂດຍບັດຫລືກັບ crypto ຈາກ $ 0.50, ສົ່ງໃຫ້ທຸກຄົນໂດຍບໍ່ເສຍຄ່າ, ການຊື້ຂາຍໃນ DeHub ແລກປ່ຽນ, ແລະສະເຕກເພື່ອປີນຂັ້ນໄດ badge.',
    congratulations: '🎉 ທ່ານ ໄດ້ ຖືກ ຈັດ ຕັ້ງ',
